import{_ as r,o as t,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-26（AI / 弹性推理预算 / 概念擦除 / 跨架构功能迁移 / RL 轨迹转运 / 表征因子可读性）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-26-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-26-ai.md"}'),g={name:"topics/ai-system-architecture/science-daily-2026-10-26-ai.md"};function i(e,o,a,c,l,d){return t(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-26-ai-弹性推理预算-概念擦除-跨架构功能迁移-rl-轨迹转运-表征因子可读性" tabindex="-1">科学日报 · 2026-10-26（AI / 弹性推理预算 / 概念擦除 / 跨架构功能迁移 / RL 轨迹转运 / 表征因子可读性） <a class="header-anchor" href="#科学日报-·-2026-10-26-ai-弹性推理预算-概念擦除-跨架构功能迁移-rl-轨迹转运-表征因子可读性" aria-label="Permalink to &quot;科学日报 · 2026-10-26（AI / 弹性推理预算 / 概念擦除 / 跨架构功能迁移 / RL 轨迹转运 / 表征因子可读性）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> — 第45期 ｜ AI 板块（5 篇，全部 arXiv，最新一批 2026-10-23 提交） 落盘说明：文件名带 <code>-ai</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-26-accordion——同一套权重-用「深度」换推理预算" tabindex="-1">科学日报 2026-10-26：Accordion——同一套权重，用「深度」换推理预算 <a class="header-anchor" href="#科学日报-2026-10-26-accordion——同一套权重-用「深度」换推理预算" aria-label="Permalink to &quot;科学日报 2026-10-26：Accordion——同一套权重，用「深度」换推理预算&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ arXiv: 2610.32492</p></blockquote><ul><li>问题：大模型要服务<strong>推理预算各异</strong>的场景，但为每种预算<strong>单独训练、维护一个模型</strong>成本很高。近期<strong>循环 Transformer（Looped Transformers）</strong> 通过<strong>参数复用</strong>支持灵活变深，难点是<strong>不同预算下性能都要稳</strong>。</li><li>方法 <strong>Accordion</strong>：基于 <strong>MoE</strong>，通过**「固定前缀层循环」（fixed-prefix layer looping）<strong>支持</strong>五种推理预算**；每种预算走<strong>一条预定义执行路径</strong>，<strong>最小预算即未循环的原模型</strong>。 <ul><li><strong>联合预训练</strong>：每个 <strong>micro-batch 采样一种预算</strong>，只优化其<strong>下一 token 预测损失</strong>，<strong>不需要额外的跨预算一致性目标</strong>（简洁是关键）。</li><li><strong>后训练保持预算</strong>：通过<strong>监督微调 + 强化学习</strong>（<strong>参数组合并</strong> + <strong>预算匹配的多教师 on-policy 蒸馏</strong>）把<strong>三个领域专家整合进一个模型</strong>。</li></ul></li><li>结果：<strong>3.6T token</strong> 预训练后，<strong>Accordion-6B-A0.5B</strong> 在 <strong>37 个任务</strong>的<strong>五类宏平均</strong>上<strong>随推理深度提升 3.01 个百分点</strong>，<strong>中间预算以一半的额外层执行次数拿到 89% 的收益</strong>；最终模型在<strong>各领域专家对应的任务—预算平均上超过专家本身</strong>，并保留数学推理与代码生成的<strong>深度依赖增益</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：要点是**「一套参数、一个深度旋钮」** —— 与 10-20「KronLSTM 长上下文线性注意力」、10-21「MemT-1.0 把记忆内化为模型计算」、10-25「METTA 把快速适应拆成两个时间尺度」合看，<strong>同一条主线是「让同一个模型在不同算力预算下都体面」</strong>。可迁移判据：<strong>当一个系统的部署条件天然分档（延迟/成本/精度）时，先问哪一维可以做成『可调旋钮』，而不是复制多份模型。</strong> 本条选的是<strong>深度</strong>（层循环），与 METTA 选<strong>记忆时间尺度</strong>、MemT 选<strong>记忆内化</strong>互为正交答案。</li></ul><hr><h2 id="科学日报-2026-10-26-非线性概念擦除——擦掉敏感属性-同时还能「反向调音」" tabindex="-1">科学日报 2026-10-26：非线性概念擦除——擦掉敏感属性，同时还能「反向调音」 <a class="header-anchor" href="#科学日报-2026-10-26-非线性概念擦除——擦掉敏感属性-同时还能「反向调音」" aria-label="Permalink to &quot;科学日报 2026-10-26：非线性概念擦除——擦掉敏感属性，同时还能「反向调音」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ arXiv: 2610.32516</p></blockquote><ul><li>问题：表征常编码<strong>性别、种族等敏感属性</strong>，<strong>擦除（erasure）<strong>它们的同时</strong>保留任务相关内容</strong>是个老问题。既有方法不完整：<strong>线性方法</strong>只能对抗<strong>线性探针</strong>；<strong>非线性方法</strong>经验上擦得更干净却<strong>缺乏形式保证</strong>、且常<strong>牺牲效用</strong>。</li><li>方法：<strong>有原则的条件自编码器（conditional autoencoder）框架</strong>做<strong>非线性概念擦除</strong>，原则是**「只擦掉敏感属性、不碰别的」<strong>；理论结果：在给定假设下，<strong>完美重构 + 群体级独立性 ⟹ 完美的非线性防御（guardedness）</strong>，并在</strong>重构不完美<strong>时有</strong>保留性保证**。</li><li>结果：在多个<strong>数据集、敏感属性与语言模型</strong>上取得更优的<strong>效用—擦除权衡</strong>，<strong>甚至超过竞争方法的监督变体</strong>，且<strong>无需目标任务标签</strong>，<strong>优化更简单、收敛更快</strong>。</li><li>副产品（意外之喜）：<strong>「概念转换」（表征引导 / steering）</strong> —— 推理时<strong>只改目标概念、不额外训练</strong>，就能生成对应<strong>不同概念值</strong>的表征，<strong>此前没有擦除方法能做到</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）：这是 10-25「隐喻是可控的几何子空间」的<strong>强化版</strong> —— 隐喻那条是「<strong>发现</strong>一个可定位子空间 → 检测与调控共用一套向量手术」；本条是「<strong>按原则构造</strong>一个子空间（条件自编码器），使<strong>擦除</strong>与<strong>反向生成</strong>成为同一个操作的两面」。可迁移判据：<strong>当你要『删掉』信息时，别只追求删得干净——问这个删除操作能不能『反过来』当生成器用；能，说明你定位的是正确的因果结构（而非只是屏蔽了表层相关）。</strong> 可写入 <code>ai-system-architecture</code> 的对齐工具箱：<strong>擦除 / 引导的「同一算子两面」判据。</strong></li></ul><hr><h2 id="科学日报-2026-10-26-ariadne——跨异构-transformer-迁移「功能」-而不是搬运参数" tabindex="-1">科学日报 2026-10-26：Ariadne——跨异构 Transformer 迁移「功能」，而不是搬运参数 <a class="header-anchor" href="#科学日报-2026-10-26-ariadne——跨异构-transformer-迁移「功能」-而不是搬运参数" aria-label="Permalink to &quot;科学日报 2026-10-26：Ariadne——跨异构 Transformer 迁移「功能」，而不是搬运参数&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ arXiv: 2610.32581</p></blockquote><ul><li>问题：把预训练 Transformer 适配到下游任务会产生<strong>任务特定更新</strong>，但<strong>为每个模型变体都复现这些更新很贵</strong>；<strong>跨不同深度/宽度复用</strong>时，<strong>参数形状不兼容、又没有统一的坐标系</strong>。</li><li>方法 <strong>Ariadne</strong>（<strong>免训练</strong>）：<strong>不在源模型上改尺寸、也不搬运参数</strong>，而是<strong>弃用「任务向量」</strong>（微调模型与基座模型参数之差），<strong>改用微调在匹配模块处引起的『激活变化』</strong> 来刻画微调： <ol><li>用<strong>局部 Procrustes 映射</strong>把这些效应对齐到<strong>目标基座</strong>；</li><li>用<strong>闭式岭回归（ridge regression）</strong> <strong>直接合成一个「原生」的目标更新</strong>。</li></ol></li><li>结果：在 Transformer 的<strong>扩宽、缩窄、语言模型迁移</strong>上，Ariadne <strong>提升目标模型性能</strong>，同时<strong>大幅降低构造更新所需的时间与内存</strong>（对比此前的<strong>跨架构 rebasin</strong> 方法）。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：<strong>「同一个功能，可以在不同坐标系的模型里用不同的参数实现」</strong> —— 所以<strong>迁移的对象应是功能（激活层面的效应），而不是参数</strong>。这与 10-22「任意 ReLU 网络均可被两层隐藏层精确模拟」、既有「用激活值而非文字描述预测对齐泛化」是同一族<strong>表征优先于参数</strong>的世界观。可迁移判据：<strong>当你要在两个『结构不同』的系统间搬运能力时，问「这个能力在对齐接口上表现为哪些可测量的量（此处=激活变化）」，然后在目标里用闭式解重造——比试图把源参数『翻译』过去更省、更稳。</strong></li></ul><hr><h2 id="科学日报-2026-10-26-knittrans——把-llm-强化学习的「轨迹搬运」这条路理顺" tabindex="-1">科学日报 2026-10-26：KnitTrans——把 LLM 强化学习的「轨迹搬运」这条路理顺 <a class="header-anchor" href="#科学日报-2026-10-26-knittrans——把-llm-强化学习的「轨迹搬运」这条路理顺" aria-label="Permalink to &quot;科学日报 2026-10-26：KnitTrans——把 LLM 强化学习的「轨迹搬运」这条路理顺&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ arXiv: 2610.32389</p></blockquote><ul><li>问题：轨迹从 <strong>rollout（采样）到训练（消费）的转运</strong>，同时影响 LLM 强化学习的<strong>学习质量</strong>与<strong>系统效率</strong>： <ul><li>强制<strong>按整批训练</strong>的要求，会<strong>推迟已完成轨迹的准入</strong> → 抬升**「架构陈旧度」（architectural staleness）<strong>（分离式流水线相对共置执行多出来的</strong>参数版本差**）；</li><li><strong>数据访问与训练消费错位</strong> → 大轨迹载荷转运时造成<strong>冗余搬动与无谓等待</strong>。</li></ul></li><li>方法 <strong>KnitTrans</strong>，三项设计协调 rollout→训练路径： <ol><li><strong>保约束的 mini-batch 准入</strong>：在组成上留出灵活度，同时<strong>校验剩余容量仍能满足配额</strong>；</li><li><strong>按需轨迹数据访问</strong>：把<strong>存储单元与消费者分配对齐</strong>，并将 <strong>micro-batch 数据准备与计算重叠</strong>；</li><li><strong>多模态编码去重</strong>：在 mini-batch 内<strong>复用编码</strong>，同时<strong>保留所有 backbone micro-batch 的梯度贡献</strong>（不是靠扔数据换速度）。</li></ol></li><li>结果：<strong>架构陈旧度最多降低 93%</strong>（对比 train-batch 准入），缩小分离式与共置执行的<strong>学质差距</strong>；<strong>多模态负载</strong>上<strong>转运延迟降两个数量级</strong>，<strong>转运 + 训练总加速最高 5.8 倍</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：这是**「训练-推理解耦的流水线」如何不牺牲学质<strong>的系统答案 —— 与 10-20「KronLSTM / 10-21 MemT 等『把成本挪到哪』的一族」不同，本条解决的是</strong>「数据在系统里怎么走」**。可迁移判据：<strong>当一个流水线被拆成两段（采样 | 训练）时，两段之间最贵的不是带宽，而是『为了批处理的整齐而让数据等待』——先设计一个『允许不整齐但保证配额』的准入规则，往往比加带宽更有效。</strong> 这条判据可直接对照外脑自身的 <code>auto_link</code>：<strong>准入规则（何时算一条边算数）比后续过滤更决定质量。</strong></li></ul><hr><h2 id="科学日报-2026-10-26-「共享」还不够——i-jepa-的预测器宽度决定表征里保留了什么" tabindex="-1">科学日报 2026-10-26：「共享」还不够——I-JEPA 的预测器宽度决定表征里保留了什么 <a class="header-anchor" href="#科学日报-2026-10-26-「共享」还不够——i-jepa-的预测器宽度决定表征里保留了什么" aria-label="Permalink to &quot;科学日报 2026-10-26：「共享」还不够——I-JEPA 的预测器宽度决定表征里保留了什么&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ arXiv: 2610.32562</p></blockquote><ul><li>问题：<strong>掩码潜变量预测方法</strong>（如 <strong>I-JEPA</strong>）想学「<strong>可预测的特征</strong>」，但<strong>究竟什么决定了它们保留哪些信息</strong>，并不清楚。</li><li>方法（很干净）：搭一个<strong>模拟器</strong>，其中<strong>图像的每个因子都已知</strong>，于是可用<strong>探针</strong>测量训练后每个因子<strong>还「可读」多少</strong>。用 <strong>I-JEPA、SimCLR、BYOL</strong> 在<strong>相同的视角对</strong>上训练<strong>小型编码器（0.7M 参数）</strong>，并探测<strong>两个视角共享的某个因子</strong>。</li><li>结果：I-JEPA 使用<strong>宽度与深度都为编码器一半的预测器</strong>（即 <strong>ViT-B 的比例</strong>），其<strong>探针得分中位数约为 SimCLR 的 40%</strong>；把预测器<strong>加宽到与编码器同宽</strong>后，<strong>在每一个训练随机种子下都反转了排序</strong>，且<strong>同时胜过另外两种方法</strong>。作者<strong>开源了模拟器与训练好的模型</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>一个常见架构默认值（预测器比编码器窄一半）是性能瓶颈，而非中性设计</strong> —— 本条把「<strong>共享信息</strong>」与「<strong>保留信息</strong>」分开：两个视角都含有的因子，<strong>不代表会被保留</strong>，<strong>取决于预测器的容量</strong>。</li><li>方法论上，<strong>「因子已知的模拟器」= 自监督学习领域的对照实验装置</strong> —— 与本库反复出现的**「用对照量钉机制」元判据**（10-24 声子 κ_aa/κ_ab 一同步一脱钩、10-25 有/无密度调制作对照）<strong>跨域同构</strong>：<strong>要判断『是什么决定了表征』，必须造一个所有因子都可控的世界。</strong> 可写入 <code>ai-brain</code> 的元判据清单。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第45期 AI 板块</p></blockquote><p>关键词：Accordion、弹性深度推理、固定前缀层循环、MoE、五种推理预算、预算匹配多教师 on-policy 蒸馏、3.6T token、37 任务宏平均 +3.01pp、非线性概念擦除、条件自编码器、群体级独立性、完美非线性 guardedness、概念转换 steering、擦除与引导同一算子两面、Ariadne、免训练、任务向量、激活变化、局部 Procrustes、闭式岭回归、跨异构 Transformer、功能优先于参数、KnitTrans、架构陈旧度 staleness −93%、保约束 mini-batch 准入、按需数据访问、多模态编码去重、总加速 5.8×、I-JEPA、预测器宽度、因子可读性、因子已知模拟器、0.7M 编码器、探针得分 40%、架构默认值是瓶颈</p><p>关联：<code>topics/ai-system-architecture/science-daily-2026-10-25-ai.md</code>（EpiSEM / Simulated Control Evals / METTA / 反向谄媚 / 隐喻子空间）、<code>topics/ai-system-architecture/science-daily-2026-10-24-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-21-ai.md</code>（MemT / KronLSTM）、<code>topics/physics/science-daily-2026-10-24-physics.md</code>（用对照量钉机制的元判据）、<code>topics/ai-brain/index.md</code></p>',26)])])}const h=r(g,[["render",i]]);export{m as __pageData,h as default};
